package dashboard.enterprise.agent.llm.audit;import com.fasterxml.jackson.databind.ObjectMapper;import core.json.JsonMapper;import dashboard.enterprise.agent.llm.model.LlmAuditEvent;import java.nio.file.*;import java.util.List;public final class LlmAuditPublisher{private static final ObjectMapper M=JsonMapper.getInstance();private LlmAuditPublisher(){}public static Path publish(Path root,List<LlmAuditEvent> events)throws Exception{Path out=root.resolve("dashboard/reports/llm/llm-audit.json");Files.createDirectories(out.getParent());M.writerWithDefaultPrettyPrinter().writeValue(out.toFile(),events);return out;}}
